import { drizzle } from 'drizzle-orm/node-postgres';
import { pgTable, serial, text } from 'drizzle-orm/pg-core';
import pg from 'pg';

export const users = pgTable('users', {
  id: serial('id').primaryKey(),
  email: text('email').notNull(),
});

// Pool is created explicitly (rather than via drizzle's `connection` option) so it
// can be closed with a correctly typed `end()`; see drizzle-team/drizzle-orm#3402.
const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL ?? 'postgres://localhost/demo' });

export const db = drizzle(pool);

export async function findUser(id: number) {
  return db.query.users.findFirst({ where: (u, { eq }) => eq(u.id, id) });
}

/** Closes the underlying pg Pool so test suites can shut down cleanly. */
export async function closeDb() {
  await pool.end();
}

